function normalizeSearch(s){return String(s??'').toLocaleLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\u200f\u0640]/g,'').replace(/\s+/g,' ').trim()}
function parseJalali(s){s=String(s||'').trim().replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)));let m=s.match(/^(\d{4})[\/\-](\d{1,2})[\/\-](\d{1,2})$/);if(!m)return null;let jy=+m[1],jm=+m[2],jd=+m[3];if(jm<1||jm>12||jd<1||jd>(jm<=6?31:jm<=11?30:30))return null;let approx=new Date(Date.UTC(jy+621,2,20));approx.setUTCDate(approx.getUTCDate()+(jm<=6?(jm-1)*31+jd-1:186+(jm-7)*30+jd-1));const fmt=new Intl.DateTimeFormat('en-u-ca-persian-nu-latn',{year:'numeric',month:'numeric',day:'numeric',timeZone:'UTC'});for(let off=-3;off<=3;off++){let d=new Date(approx);d.setUTCDate(d.getUTCDate()+off);let parts=Object.fromEntries(fmt.formatToParts(d).filter(x=>x.type!=='literal').map(x=>[x.type,+x.value]));if(parts.year===jy&&parts.month===jm&&parts.day===jd)return d.toISOString().slice(0,10)}return null}
